'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var tryRequire = require( '@stdlib/utils/try-require' );


// FIXTURES //

var small = require( './fixtures/python/small.json' );
var medium = require( './fixtures/python/medium.json' );
var large = require( './fixtures/python/large.json' );


// VARIABLES //

var logitf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( logitf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof logitf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `NaN` when provided `NaN`', opts, function test( t ) {
	var y = logitf( NaN );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` when provided a number outside `[0,1]`', opts, function test( t ) {
	var y = logitf( 1.2 );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	y = logitf( -0.1 );
	t.strictEqual( isnanf( y ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-Infinity` when provided `0`', opts, function test( t ) {
	var y = logitf( 0.0 );
	t.strictEqual( y, NINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `+Infinity` when provided `1`', opts, function test( t ) {
	var y = logitf( 1.0 );
	t.strictEqual( y, PINF, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the logit of `x` for the interval `(0,0.25]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	expected = small.expected;
	x = small.x;
	for ( i = 0; i < x.length; i++ ) {
		y = logitf( x[i] );
		e = float64ToFloat32( expected[i] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the logit of `x` for the interval `[0.25,0.75]`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	expected = medium.expected;
	x = medium.x;
	for ( i = 0; i < x.length; i++ ) {
		y = logitf( x[i] );
		e = float64ToFloat32( expected[i] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the logit of `x` for the interval `[0.75,1)`', opts, function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	expected = large.expected;
	x = large.x;
	for ( i = 0; i < x.length; i++ ) {
		y = logitf( x[i] );
		e = float64ToFloat32( expected[i] );
		t.strictEqual( isAlmostSameValuef( y, e, 1 ), true, 'returns expected value' );
	}
	t.end();
});
